    this._scene = scene;
    this._renderer = renderer;
    this._clock = new THREE.Clock();
  }

  // Method to set the camera position
  public setPosition(x: number, y: number, z: number): void {
    this._camera.position.set(x, y, z);
  }

  // Method to set the camera target (the point the camera is looking at)
  public setTarget(x: number, y: number, z: number): void {
    if (!this._camera.target) {
      this._camera.target = new THREE.Vector3(x, y, z);
    } else {
      this._camera.target.set(x, y, z);
    }
  }

  // Method to set the camera up vector (used for calculations like normal vectors)
