function switchAdjectiveOrder(sentence) {
  // Define a list of common English adjectives for identification
  const adjectives = /([a-z]+(ed|ly|er|est|erest)\b)([^\s]+[a-z]+)|([a-z]+[^,.\?!]*[,.]|\b[a-z][^,.\?!]*[,.]|\b[a-z]+[^,.\?!]*[!]|[^,.\?!]*[!])$/g;

  let match, words = sentence.split(' ');
  let newWords = [];

  while ((match = adjectives.exec(sentence)) !== null) {
    const index = words.findIndex(word => word === match[1] || (match[2] && word.startsWith(match[2]))) + (match[2] ? match.index : 0);
    newWords.push(words[index - 1], match[0]);
    words.splice(index, 1);
  }

  return newWords.concat(words.slice(newWords.length)).join(' ') + '.';
}

