console.log(switchAdjectiveOrder("The quick brown fox jumps over the lazy dog")); // "The lazy brown fox jumps over the quick dog."
console.log(switchAdjectiveOrder("Red hot chili peppers are delicious")); // "Delicious red hot chili peppers are."
```

