function switchAdjectiveOrder(sentence) {
  // Define regex pattern for matching adjectives and their positions
  const regex = /([\w']+ (\b[jkwqfgdmbrvzpcshlnrtgp]\w*)|[a-z][^ ]+( [a-z][a-z])?)\s+(the|an|a)\s+(?:[A-Z].*\b)/g;

