```javascript
const axios = require('axios'); // Make sure to install axios package using npm or yarn before running this code

async function postMessageToSlackChannel(text, channel) {
  try {
    const options = {
      method: 'post',
      url: `https://slack.com/api/chat.postMessage`,
      headers: { 'Content-Type': 'application/json' },
      data: {
        channel: channel,
        text: text
      }
    };

    const response = await axios(options);

    if (response.status === 200) {
      console.log(`Message posted successfully to channel #${channel}: ${text}`);
    } else {
      throw new Error(`Error posting message to channel #${channel}. Status code received: ${response.status}`);
    }
  } catch (error) {
    console.error(`Error posting message to channel #${channel}: ${error.message}`);
  }
}

// Example usage:
