```cpp
#include <iostream>
#include <vector>
#include <nlohmann/json.hpp> // Include json library for parsing JSON
using json = nlohmann::json;
int main() {
    std::string json_str = R"({"array":[5, 2, 9, 1, 5, 6]})"; // JSON string
    json j = json::parse(json_str); // Parse JSON
    int n = j["array"].size(); // Get array size
    int arr[n]; // Allocate stack memory for the array
    for (int i = 0; i < n; ++i) {
        arr[i] = j["array"][i].get<int>(); // Extract integers from JSON into the array
    }
    for (int i = 0; i < n - 1; ++i) {
        for (int j = 0; j < n - i - 1; ++j) {
            if (arr[j] > arr[j+1]) {
                std::swap(arr[j], arr[j+1]);
            }
        }
    }
    // Print sorted array
    for (int i = 0; i < n; ++i) {
        std::cout << arr[i] << " ";
    }
    std::cout << std::endl;
    return 0;
}
```
