First, let's focus on implementing the bubble sort algorithm:

```cpp
#include <vector>
#include <iostream>

void bubbleSort(std::vector<int>& arr) {
    int n = static_cast<int>(arr.size());
    bool swapped;
    for (int i = 0; i < n - 1; ++i) {
        swapped = false;
        for (int j = 0; j < n - i - 1; ++j) {
            if (arr[j] > arr[j+1]) {
                std::swap(arr[j], arr[j+1]);
                swapped = true;
            }
        }
        // If no two elements were swapped in inner loop, then the array is already sorted
        if (!swapped) break;
    }
}

int main() {
    std::vector<int> arr = {5, 2, 9, 1, 5, 6};
    bubbleSort(arr);
    for (auto num : arr) {
        std::cout << num << ' ';
    }
    return 0;
}
```
