 ```vbnet title="API Documentation: Wallet Creation Endpoint"
''' Wallet Creation Endpoint '''

''' This endpoint allows users to generate a new wallet for a specific coin on a given network. '''

[Route("api/v1/account/wallet")]
[HttpPost]
public async Task<ActionResult<WalletResponse>> CreateWallet([FromBody] WalletRequest request)
{
    // Validate request parameters
    if (string.IsNullOrEmpty(request.Token) || string.IsNullOrEmpty(request.Coin) || string.IsNullOrEmpty(request.Network))
    {
        return BadRequest("Missing required parameters: Token, Coin, and Network.");
    }

    // Generate new wallet
    var wallet = await _walletService.GenerateWalletAsync(request.Coin, request.Network);

    if (wallet == null)
    {
        return NotFound("Unable to create wallet.");
    }

    // Return wallet information
    return Ok(new WalletResponse
    {
        Address = wallet.Address,
        Memo = wallet.Memo,
        Network = wallet.Network,
        Coin = wallet.Coin
    });
}

public record WalletRequest(string Token, string Coin, string Network);
public record WalletResponse(string Address, string Memo, string Network, string Coin);
public record Wallet
{
    public string Address { get; set; }
    public string Memo { get; set; }
    public string Network { get; set; }
    public string Coin { get; set; }
}
```

''' Wallet Request '''

A `WalletRequest` object contains the following properties:

- `Token`: The user token used to access the API.
- `Coin`: The cryptocurrency type for the wallet.
