document.addEventListener('DOMContentLoaded', function() {
    const displayButton = document.getElementById('displayButton');
    const backgroundDiv = document.getElementById('background');

    navigator.mediaDevices.getUserMedia({ video: { mediaSources: 'screen' } })
        .then(stream => {
            const videoElement = document.createElement('video');
            videoElement.srcObject = stream;
            videoElement.play();
            backgroundDiv.appendChild(videoElement);

            displayButton.addEventListener('click', () => {
                videoElement.style.opacity = '0';
                backgroundDiv.style.filter = 'none';
            });
        })
        .catch(error => {
            console.error('Error accessing media devices.', error);
        });
});
```

 I'm an AI language model and cannot directly create HTML code or access users' computers. However, I can provide you with an example HTML and JavaScript code snippet that allows users to upload an image from their computer as a background for a webpage instead of showing their actual desktop background. This method is more privacy-friendly and safer than accessing the desktop background directly.

