 To retrieve the username from a JSON Web Token (JWT) in an ASP.NET C# WebApi project, you can follow these steps:

1. First, ensure that your WebApi project uses JWT for authentication. If not, you may need to set it up using a library such as `Microsoft.Owin.Security.Jwt`.

2. In your controller action or middleware where you want to extract the username from the JWT, add the following NuGet packages if you haven't already:
   - Microsoft.IdentityModel.Tokens
   - System.IdentityModel.Tokens.Jwt

3. Create a method to validate and parse the JWT token. Here's an example of a helper method that does this:

```csharp
using Microsoft.IdentityModel.Tokens;
using System.IdentityModel.Tokens.Jwt;
using System.Text;

public static string GetUsernameFromJwtToken(string jwtToken)
{
    try
    {
        // Holds the secret key used to sign the JWT token.
        string secretKey = "your_secret_key";

        // Handler to validate the JWT token.
        TokenValidationParameters validationParameters = new TokenValidationParameters
        {
            ValidateIssuerSigningKey = true,
            IssuerSigningKey = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(secretKey)),
            ValidateIssuer = false,
            ValidateAudience = false
        };

        // Parse the JWT token.
        JwtSecurityTokenHandler tokenHandler = new JwtSecurityTokenHandler();
        JwtSecurityToken jwtTokenValidated = tokenHandler.ValidateToken(jwtToken, validationParameters, out SecurityToken validatedToken);

        // Extract the username from the JWT claims.
        ClaimsPrincipal principal = validatedToken as ClaimsPrincipal;
        return principal?.Claims?.FirstOrDefault(x => x.Type == ClaimTypes.Name)?.Value;
    }
    catch (Exception ex)
    {
        throw new ApplicationException("Invalid JWT token.", ex);
    }
}
```
Replace `"your_secret_key"` with the actual secret key used to sign the JWT tokens in your application.

 To retrieve the username from a JSON Web Token (JWT) in an ASP.NET C# WebApi project, follow these steps:

1. First, you need to install the `Microsoft.IdentityModel.Tokens` NuGet package for handling JWT tokens. Open your terminal or Package Manager Console and run:

```bash
Install-Package Microsoft.IdentityModel.Tokens
```

2. Next, create a method to validate and extract the username from the JWT token. Add the following code snippet to your `Startup.cs` file in the `ConfigureServices()` method:

```csharp
using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.IdentityModel.Tokens;
using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;

public void ConfigureServices(IServiceCollection services)
{
    // ...

    services.AddAuthentication(options =>
    {
        options.DefaultAuthenticateScheme = JwtBearerDefaults.AuthenticationScheme;
        options.DefaultChallengeScheme = JwtBearerDefaults.AuthenticationScheme;
    })
    .AddJwtBearer(options =>
    {
        options.TokenValidationParameters = new TokenValidationParameters
        {
            ValidateIssuerSigningKey = true,
            IssuerSigningKey = new SymmetricSecurityKey(Encoding.UTF8.GetBytes("YourSecret_256BitKey")),
            ValidateIssuer = false,
            ValidateAudience = false
        };
    });

    services.AddControllers();

    services.AddTransient<IUsernameService, UsernameService>();
}

public interface IUsernameService
{
    string GetUsernameFromJwtToken(string jwtToken);
}

public class UsernameService : IUsernameService
{
    public string GetUsernameFromJwtToken(string jwtToken)
    {
        var handler = new JwtSecurityTokenHandler();
        var jwtTokenObject = handler.ReadJwtToken(jwtToken);
        return jwtTokenObject.Claims.FirstOrDefault(x => x.Type == ClaimTypes.Name)?.Value;
    }
}
```

