        strcat(result, argv[i]);
        strcat(result, " ");
    }
    strcat(result, argv[argc - 1]);

    return result;
}

void main() {
    int argc = 4;
    char *argv[] = {"arg1", "arg2", "arg3", "arg4"};

    char *cstring = concatArgs(argc, argv);
    printf("Concatenated string: %s\n", cstring);

    free(cstring);
}
```

