import { createContext } from 'react';

export const ToastContext = createContext();

export const ToastProvider = ({ children }) => {
  const [message, setMessage] = React.useState('');
  const [show, setShow] = React.useState(false);

  const value = { message, show, setMessage, setShow };

  return (
    <ToastContext.Provider value={value}>{children}</ToastContext.Provider>
  );
};
```

2. Now, create a functional component for the Toast component in a new file named `Toast.js`:

```javascript
import React from 'react';
import { ToastContext } from './ToastContext';

const Toast = () => {
  const { message, show } = React.useContext(ToastContext);

  if (!show) return null;

  return (
    <div className="toast">
      <span>{message}</span>
    </div>
  );
};

export default Toast;
```

3. Finally, wrap your main application or the part of it where you want to display the toast notifications with the `ToastProvider`. Use the `Toast` component as a child of the provider.

