func rearrangePhrase(_ phrase: String) -> String {
    let words = ["appreciation", "blessings", "gratitude", "hope", "joy"]
    let sortedLetters = phrase.filter { !$0.isWhitespace }.sorted()

    var optimisticPhrases: [String] = []
    for word in words {
        var shuffledLetters: [Character] = Array(word.lowercased())
        shuffle(&shuffledLetters)

        let index = phrase.firstIndex(of: word.first!)!
        let subphrase = String(phrase[index..<(index + word.count))).filter { !$0.isWhitespace }
        let sortedSubLetters = subphrase.sorted()

        for i in 0..<shuffledLetters.count {
            shuffledLetters[i] = sortedSubLetters[i]
        }

        optimisticPhrases.append(String(shuffledLetters))
    }

    let optimisticPhrase = optimisticPhrases.joined(separator: " ")
    return "With a grateful heart and an optimistic mind, \(optimisticPhrase)"
}
func shuffle(_ array: inout [Character]) {
    guard array.count > 1 else { return }

    for i in stride(from: array.count - 1, through: 0, by: -1) {
        let j = Int.random(in: 0...i)
        swap(&array[i], &array[j])
    }
}
