import React from 'react';
import { Text, Provider as TextProvider } from 'react-text';

const RemoveWidowsText = ({ children }) => {
  const lines = React.useMemo(
    () => (children && children.toString().split('\n')) || [],
    [children],
  );

  const [state, setState] = React.useState({ lines });

  React.useEffect(() => {
    if (!lines.length) return;

    const lastLine = lines[lines.length - 1];
    const words = lastLine.trim().split(' ');

    // If the last line has more than one word, it's not a widow
    const isWidow = words.length <= 1;

    setState((prevState) => ({ lines: prevState.lines.map((line, index) => {
      if (index === lines.length - 1) {
        return isWidow ? line.slice(0, -1) : line;
      } else {
        return line;
      }
    }))});
  }, [lines]);

  return <TextProvider text={state.lines.join('\n')}>{children}</TextProvider>;
};

export default function RemoveWidows({ children }) {
  return (
    <TextProvider>
      <RemoveWidowsText>{children}</RemoveWidowsText>
    </TextProvider>
  );
}
```

