 Here's the code for `redis.js` with the `RedisClient` class and an exported instance named `redisClient`. This implementation utilizes the `ioredis` library for interacting with Redis. Make sure you have it installed before running the code:

```javascript
const ioredis = require('ioredis');

class RedisClient {
  constructor() {
    this.client = new ioredis();

    this.client.on('error', (err) => {
      console.error('Error connecting to Redis:', err);
    });
  }

  async isAlive() {
    try {
      return await this.client.ping();
    } catch (err) {
      console.error('Error checking Redis connection:', err);
      return false;
    }
  }

  async get(key) {
    return new Promise((resolve, reject) => {
      this.client.get(key, (err, value) => {
        if (err) return reject(err);
        resolve(value);
      });
    });
  }

  async set(key, value, duration) {
    return new Promise((resolve, reject) => {
      this.client.set(key, value, 'EX', duration, (err, result) => {
        if (err) return reject(err);
        resolve(result);
      });
    });
  }

  async del(key) {
    return new Promise((resolve, reject) => {
      this.client.del(key, (err, result) => {
        if (err) return reject(err);
        resolve(result);
      });
    });
  }
}

const redisClient = new RedisClient();
module.exports = { RedisClient, redisClient };
```

