 To identify if a given sentence in Go contains a double negative, you can follow these steps:

1. Define a slice of specific negative words.
2. Tokenize the input sentence into words.
3. Iterate through each word in the tokenized sentence.
4. Check if the current word is a negative word or the word "not".
5. If yes, check if the next word is also a negative word or "not".
6. If both conditions are satisfied, print a message indicating that the sentence contains a double negative.

Here's an example Go code snippet that implements this logic:

```go
package main

import (
	"fmt"
	"strings"
)

func main() {
	negativeWords := []string{"ain't", "am not", "aren't", "doesn't", "don't", "isn't", "is not", "aren't I", "wasn't", "weren't", "won't"}
	sentence := "He isn't not worried about the coronavirus situation"

	words := strings.Split(sentence, " ")
	prevWord := ""
	for i := range words {
		currentWord := words[i]
		if containsNegation(currentWord) || currentWord == "not" {
			if prevWord != "" && containsNegation(prevWord) {
				fmt.Println("Double Negative Detected!")
				return
			}
			prevWord = currentWord
		} else {
			prevWord = ""
		}
	}
	fmt.Println("No Double Negatives Found.")
}

func containsNegation(word string) bool {
	for _, negation := range negativeWords {
		if strings.EqualFold(word, negation) {
			return true
		}
	}
	return false
}
```

