			fmt.Println("The sentence contains a double negative.")
			return
		}
	}

	fmt.Println("The sentence does not contain a double negative.")
}

// Function to check if the current word is a double negative.
func isDoubleNegative(currentWord, nextWord string) bool {
	// Check if current word is a negative word.
	if contains(negativeWords, currentWord) {
		// If next word is "not" followed by another negative word, then it's a double negative.
		if len(nextWord) > 0 && (strings.HasPrefix(nextWord, "not") || contains(negativeWords, nextWord)) {
			return true
		}
	}
	return false
}

