```powershell
# Import the required module for Active Directory
Import-Module ActiveDirectory

# Function to check if a given SID is present in the SID history of any user or group in the domain
function Get-ADObjectWithSidInSidHistory ($sid) {
    $filter = "(&(objectClass=user)(objectClass=group)(msDS-ManagedBy:1.2.840.113556.1.4.803:=$($env:USERDNSDOMAIN))(msDS-ProtectedFromAccidentalDeletion:$false)(msDS-SIDHistory:*))"
    $searcher = New-Object -ComObject "ADSISEARCHER"
    $searcher.Filter = $filter
    $searcher.SearchRoot = [adsi]"LDAP://DC=$($env:COMPUTERNAME),DC=$($env:USERDNSDOMAIN)"
    $results = @()
    Do {
        $result = $searcher.FindNext()
        If ($result -ne $null) {
            $obj = New-Object PSObject -Property @{
                DistinguishedName = $result.Path
                SID = (Get-ADObject -LDAPFilter "(SID=$sid)" -Properties msDS-SIDHistory).msDS-SIDHistory | Select-Object -ExpandProperty Value
            }
            $results += $obj
        }
    } While ($searcher.HasMoreResults)
    return $results
}

